/**  Which part of the loop a session is in. */
export type Phase = "focus" | "break";

/**  One live preset, with what the list needs to say about it. */
export type PresetEntry = {
	id: PresetId,
	name: string,
	focusMin: number,
	breakMin: number,
	longBreakMin: number,
	rounds: number,
	/**  One of the three default presets. */
	isDefault: boolean,
	/**
	 *  A default preset whose name or lengths differ from the shipped ones. Always false for
	 *  a user's own preset.
	 */
	isChanged: boolean,
};

export type PresetError = PresetError_Serialize | PresetError_Deserialize;

/**  Why a preset call failed. */
export type PresetErrorKind = "invalid" | "duplicateName" | "limit" | "lastPreset" | "notFound" | "unavailable" | "write";

export type PresetError_Deserialize = {
	kind: PresetErrorKind,
	/**  The field that is out of range, for `invalid`. */
	field?: PresetField | null,
	message: string,
};

export type PresetError_Serialize = {
	kind: PresetErrorKind,
	/**  The field that is out of range, for `invalid`. */
	field: PresetField | null,
	message: string,
};

/**  The field of a [`PresetDef`] that is out of range. */
export type PresetField = "name" | "focus_min" | "break_min" | "long_break_min" | "rounds";

/**  Opaque preset identifier (a UUIDv7, or a default's fixed id), serialized as a bare string. */
export type PresetId = string;

/**  The fields of a preset to change; each absent field stays as it is. */
export type PresetPatch = PresetPatch_Serialize | PresetPatch_Deserialize;

/**  The fields of a preset to change; each absent field stays as it is. */
export type PresetPatch_Deserialize = {
	name?: string | null,
	focusMin?: number | null,
	breakMin?: number | null,
	longBreakMin?: number | null,
	rounds?: number | null,
};

/**  The fields of a preset to change; each absent field stays as it is. */
export type PresetPatch_Serialize = {
	name: string | null,
	focusMin: number | null,
	breakMin: number | null,
	longBreakMin: number | null,
	rounds: number | null,
};

/**  Opaque session identifier, serialized as a bare string. */
export type SessionId = string;

/**  The saved settings. */
export type Settings = {
	theme: Theme,
	/**  The selected library preset (`timer.preset`). */
	presetId: PresetId,
	/**  How many times "+10 min" is offered in one session, 0 to 3 (`timer.extension_cap`). */
	extensionCap: number,
	/**  Keep going in 10-minute steps when a focus ends (`timer.auto_continue`). */
	autoContinue: boolean,
	/**  Where auto-continue steps stop, in minutes, 60 to 150 (`timer.longest_focus_min`). */
	longestFocusMin: number,
	/**  Note, once a day, when the day's focus passes `deep_cap_hours` (`timer.deep_cap_on`). */
	deepCapOn: boolean,
	/**  The deep-hours cap, 2 to 8 hours (`timer.deep_cap_hours`). */
	deepCapHours: number,
	notifySessionEnd: boolean,
	/**  Notify two minutes before the end (`notify.two_minutes`). */
	notifyTwoMinutes: boolean,
	/**
	 *  The start or pause shortcut: a canonical accelerator or `"off"` (`keys.start_pause`).
	 *  Changed only through `keyboard_set_shortcut`; `settings_set` ignores it.
	 */
	startPauseKeys: string,
	/**  The capture shortcut, the same (`keys.capture`). */
	captureKeys: string,
	/**  Space, F and P on Today and Space in Focus view act (`keys.single_key`). */
	singleKey: boolean,
};

/**  The settings changed. */
export type SettingsChanged = Settings;

export type SettingsError = {
	kind: SettingsErrorKind,
	message: string,
};

/**  Why saving settings failed. */
export type SettingsErrorKind = "invalidSpec" | "unavailable" | "write";

/**  A place on the Settings page: a section or a field. Matches the webview's `SettingsTarget`. */
export type SettingsTarget = "general" | "timer" | "notifications" | 
/**  Settings › Keyboard. */
"keyboard" | "appsAndSites" | "about" | "focusMinutes" | "breakMinutes" | 
/**  The *Keep going automatically* row in Timer. */
"keepGoing";

/**  A global shortcut: it works from any app. */
export type ShortcutId = 
/**  Starts the selected preset, or pauses or resumes a running session. */
"startPause" | 
/**  Opens the capture panel. */
"capture";

/**  Whether a global shortcut is working now. Memory only: computed at launch and after each change. */
export type ShortcutStatus = "registered" | "off" | 
/**  Saved but not registered: another app holds it, or it could not be registered. */
"failed";

/**  One global shortcut as the webview shows it. */
export type ShortcutView = ShortcutView_Serialize | ShortcutView_Deserialize;

/**  One global shortcut as the webview shows it. */
export type ShortcutView_Deserialize = {
	/**  The canonical accelerator ("Control+Alt+KeyF"); `None` when it is off. */
	keys?: string | null,
	/**  The keys as glyphs ("⌃⌥F"). */
	display?: string | null,
	/**  The keys as words ("Control-Option-F"). */
	spoken?: string | null,
	status: ShortcutStatus,
};

/**  One global shortcut as the webview shows it. */
export type ShortcutView_Serialize = {
	/**  The canonical accelerator ("Control+Alt+KeyF"); `None` when it is off. */
	keys: string | null,
	/**  The keys as glyphs ("⌃⌥F"). */
	display: string | null,
	/**  The keys as words ("Control-Option-F"). */
	spoken: string | null,
	status: ShortcutStatus,
};

/**  Why a spike command failed, with a message for the log. */
export type SpikeError = {
	kind: SpikeErrorKind,
	message: string,
};

/**  Which spike error: `disabled` wins over `unsupported`. */
export type SpikeErrorKind = "disabled" | "unsupported" | "platform";

/**  Whether the spike runs, and whether this OS has an implementation installed. */
export type SpikeStatus = {
	enabled: boolean,
	platformSupported: boolean,
};

/**  Sent to window `main` when usage changed; the dev panel then calls `spike_usage`. */
export type SpikeUsageChanged = null;

/**  Asks to start a session. */
export type StartRequest = {
	/**  Start the built-in two-minute focus; otherwise the selected preset. */
	quick: boolean,
};

/**  Whether the session store could be used. */
export type StoreStatus = "ok" | "unavailable" | "newer";

/**  How firmly a line is backed by evidence. Unlabelled lines have a source or are plain product principle. */
export type SuggestionLabel = "optional" | "experimental";

/**  One break suggestion: the line and how firmly the evidence backs it. */
export type SuggestionView = SuggestionView_Serialize | SuggestionView_Deserialize;

/**  One break suggestion: the line and how firmly the evidence backs it. */
export type SuggestionView_Deserialize = {
	text: string,
	/**  `optional` or `experimental`; `None` for a line with a source or a product principle. */
	label?: SuggestionLabel | null,
};

/**  One break suggestion: the line and how firmly the evidence backs it. */
export type SuggestionView_Serialize = {
	text: string,
	/**  `optional` or `experimental`; `None` for a line with a source or a product principle. */
	label: SuggestionLabel | null,
};

/**  The colour theme the person chose. */
export type Theme = 
/**  Follow the system appearance. */
"system" | 
/**  Always light. */
"light" | 
/**  Always dark. */
"dark";

export type TimerCommandError = {
	kind: TimerCommandErrorKind,
	message: string,
};

/**  Why a timer command failed. */
export type TimerCommandErrorKind = "alreadyRunning" | "nothingRunning" | "wrongState" | "invalidSpec" | "store" | 
/**  "+10 min" was asked past the extension cap. */
"extensionCap";

/**  The view plus milestones the webview has not seen yet. */
export type TimerState = TimerState_Serialize | TimerState_Deserialize;

/**  The view plus milestones the webview has not seen yet. */
export type TimerState_Deserialize = {
	view: TimerView_Deserialize,
	pending: MilestoneEvent_Deserialize[],
};

/**  The view plus milestones the webview has not seen yet. */
export type TimerState_Serialize = {
	view: TimerView_Serialize,
	pending: MilestoneEvent_Serialize[],
};

/**  Everything the webview shows about the timer, emitted as `timer-tick`. */
export type TimerView = TimerView_Serialize | TimerView_Deserialize;

/**  Everything the webview shows about the timer, emitted as `timer-tick`. */
export type TimerView_Deserialize = {
	state: EngineState,
	phase: Phase,
	mode: Mode,
	remainingMs: number,
	remaining: string,
	remainingLabel: string,
	progress: number,
	sessionId?: SessionId | null,
	/**  The library preset the running session started with; `None` while idle and for `quick`. */
	presetId?: PresetId | null,
	/**  The snapshot's name, or "Just 2 minutes" for `quick`; `None` while idle. */
	presetName?: string | null,
	/**  The running session is the built-in two-minute start. */
	quick: boolean,
	/**  The snapshot's break length in minutes; `None` while idle and for `quick`. */
	breakMin?: number | null,
	finish?: string | null,
	/**
	 *  The session's planned focus length in whole minutes, fixed at start (an edit to the preset
	 *  mid-session does not move it); `None` while idle.
	 */
	plannedMin?: number | null,
	store: StoreStatus,
	notifications: NotificationStatus,
	/**  Which break it is, during a break. */
	breakKind?: BreakKind | null,
	/**  "+10 min" taken so far in this session, in a break too (the focus's count). */
	extensions: number,
	/**  "+10 min" is on offer now: under the cap, and not while paused or for `quick`. */
	canExtend: boolean,
	/**  The break's line, during a break only. */
	suggestion?: SuggestionView_Deserialize | null,
	/**  "Keep going?", while idle after a `quick` session and auto-continue is off. */
	offer?: Offer | null,
	/**  "Still going · ends 15:40", while running in an automatic step. */
	checkIn?: string | null,
	/**  The quiet line while idle once today's focus has passed the deep-hours cap. */
	capLine?: string | null,
	/**  A one-time hint for the status line; `None` once shown and while none is due. */
	hint?: Hint | null,
	/**  A one-time tip for the status row, after a session end; `None` once seen and while none is due. */
	tip?: TipId | null,
	/**  The first-run welcome line shows: no session was ever started on this device. */
	welcome: boolean,
};

